-- New opt-in only. Existing OAuth and sandbox grants are unchanged.
CREATE TABLE private_build_grants(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,client_id TEXT NOT NULL REFERENCES mcp_clients(id) ON DELETE CASCADE,owner_id TEXT NOT NULL REFERENCES users(id),created_at INTEGER NOT NULL,revoked_at INTEGER);
CREATE UNIQUE INDEX private_build_active_client ON private_build_grants(client_id) WHERE revoked_at IS NULL;
CREATE TABLE private_build_packages(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,owner_id TEXT NOT NULL REFERENCES users(id),client_id TEXT NOT NULL REFERENCES mcp_clients(id),token_id TEXT NOT NULL REFERENCES mcp_access_tokens(id),source_proposal TEXT NOT NULL UNIQUE REFERENCES proposals(id),backend_proposal TEXT NOT NULL UNIQUE REFERENCES backend_proposals(id),base_revision INTEGER NOT NULL,base_backend_digest TEXT,digest TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','approved','rejected')),grant_id TEXT REFERENCES private_build_grants(id),created_at INTEGER NOT NULL,decided_at INTEGER,preparing_at INTEGER,preview_id TEXT REFERENCES previews(id) ON DELETE SET NULL);
CREATE TRIGGER private_build_immutable BEFORE UPDATE OF project_id,owner_id,client_id,token_id,source_proposal,backend_proposal,base_revision,base_backend_digest,digest,grant_id ON private_build_packages BEGIN SELECT RAISE(ABORT,'immutable_private_build'); END;
CREATE TRIGGER private_build_approve BEFORE UPDATE OF status ON private_build_packages BEGIN
 SELECT CASE WHEN OLD.status<>'pending' THEN RAISE(ABORT,'private_build_terminal') END;
 SELECT CASE WHEN NEW.status='approved' AND NOT EXISTS(SELECT 1 FROM projects p JOIN memberships m ON m.workspace_id=p.workspace_id JOIN proposals s ON s.id=NEW.source_proposal JOIN backend_proposals b ON b.id=NEW.backend_proposal JOIN mcp_access_tokens t ON t.client_id=NEW.client_id AND t.project_id=NEW.project_id AND t.user_id=NEW.owner_id JOIN mcp_clients c ON c.id=NEW.client_id WHERE p.id=NEW.project_id AND p.revision=NEW.base_revision AND m.user_id=NEW.owner_id AND m.role='owner' AND s.status='pending' AND s.project_id=p.id AND s.base_revision=p.revision AND b.status='pending' AND b.project_id=p.id AND c.project_id=p.id AND c.owner_id=NEW.owner_id AND c.revoked_at IS NULL AND t.client_id=c.id AND t.project_id=p.id AND t.user_id=NEW.owner_id AND t.revoked_at IS NULL AND t.expires_at>NEW.decided_at AND EXISTS(SELECT 1 FROM json_each(t.scopes) WHERE value='sandbox.write') AND EXISTS(SELECT 1 FROM json_each(t.scopes) WHERE value='schema.propose') AND EXISTS(SELECT 1 FROM json_each(t.scopes) WHERE value='checks.run') AND EXISTS(SELECT 1 FROM json_each(t.scopes) WHERE value='preview.create') AND json_extract(b.config_json,'$.version')=2 AND NEW.base_backend_digest IS COALESCE((SELECT digest FROM backend_proposals WHERE project_id=p.id AND status='approved' ORDER BY decided_at DESC,id DESC LIMIT 1),(SELECT digest FROM project_backends WHERE project_id=p.id))) THEN RAISE(ABORT,'private_build_stale_or_revoked') END;
 SELECT CASE WHEN NEW.status='approved' AND NEW.grant_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM private_build_grants g JOIN mcp_access_tokens t ON t.id=NEW.token_id WHERE g.id=NEW.grant_id AND g.project_id=NEW.project_id AND g.client_id=NEW.client_id AND g.owner_id=NEW.owner_id AND g.revoked_at IS NULL AND EXISTS(SELECT 1 FROM json_each(t.scopes) WHERE value='sandbox.write') AND EXISTS(SELECT 1 FROM json_each(t.scopes) WHERE value='schema.propose') AND EXISTS(SELECT 1 FROM json_each(t.scopes) WHERE value='checks.run') AND EXISTS(SELECT 1 FROM json_each(t.scopes) WHERE value='preview.create')) THEN RAISE(ABORT,'private_build_grant_revoked') END;
END;
CREATE TRIGGER private_build_apply AFTER UPDATE OF status ON private_build_packages WHEN NEW.status='approved' BEGIN
 UPDATE proposals SET status='approved',approved_by=NEW.owner_id,decided_at=NEW.decided_at WHERE id=NEW.source_proposal;
 UPDATE backend_proposals SET status='approved',approved_by=NEW.owner_id,decided_at=NEW.decided_at WHERE id=NEW.backend_proposal;
 INSERT INTO backend_audit(project_id,actor_id,action,digest,created_at) SELECT NEW.project_id,NEW.owner_id,'private_build_schema_approved',digest,NEW.decided_at FROM backend_proposals WHERE id=NEW.backend_proposal;
END;

CREATE TRIGGER private_build_source_combined BEFORE UPDATE OF status ON proposals WHEN EXISTS(SELECT 1 FROM private_build_packages WHERE source_proposal=NEW.id AND status='pending') BEGIN SELECT RAISE(ABORT,'private_build_combined_review_required'); END;
CREATE TRIGGER private_build_schema_combined BEFORE UPDATE OF status ON backend_proposals WHEN EXISTS(SELECT 1 FROM private_build_packages WHERE backend_proposal=NEW.id AND status='pending') BEGIN SELECT RAISE(ABORT,'private_build_combined_review_required'); END;

CREATE TRIGGER private_build_capacity BEFORE INSERT ON private_build_packages WHEN (SELECT count(*) FROM private_build_packages WHERE project_id=NEW.project_id AND created_at>NEW.created_at-86400000)>=20 BEGIN SELECT RAISE(ABORT,'private_build_daily_limit'); END;
